<source_code>
import java.io.*;
import java.util.*;

public class A421 {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);

        int a = in.nextInt(); // number of initial letters
        int b = in.nextInt(); // letters Mister B appends per move
        int l = in.nextInt(); // left bound of segment
        int r = in.nextInt(); // right bound of segment

        // Build the string s up to position r
        StringBuilder s = new StringBuilder();

        // Initial string: first a lowercase letters
        for (int i = 0; i < a; i++) {
            s.append((char)('a' + i));
        }

        // Simulate the game until we have at least r characters
        while (s.length() < r) {
            // Mister B's move: append b letters (optimally to minimize distinct letters in [l,r])
            // To minimize distinct letters in the target segment, Mister B should append letters
            // that are already present in the string, especially letters that will fall in [l,r]
            // Since Mister B moves first and can choose any letters, he will try to minimize
            // distinct letters in the final segment [l,r]

            // For optimal play, Mister B should append the same letter repeatedly (the one that
            // appears most in the current string, or 'a' for simplicity)
            char letterToAppend = 'a';
            // Find the most frequent letter in the current string to minimize distinct letters
            int[] freq = new int[26];
            for (int i = 0; i < s.length(); i++) {
                freq[s.charAt(i) - 'a']++;
            }
            int maxFreq = 0;
            for (int i = 0; i < 26; i++) {
                if (freq[i] > maxFreq) {
                    maxFreq = freq[i];
                    letterToAppend = (char)('a' + i);
                }
            }

            for (int i = 0; i < b; i++) {
                s.append(letterToAppend);
            }

            // Computer's move: append a letters based on the last a characters
            if (s.length() >= r) break;

            String suffix = s.substring(Math.max(0, s.length() - a), s.length());
            int[] used = new int[26];
            for (int i = 0; i < suffix.length(); i++) {
                used[suffix.charAt(i) - 'a'] = 1;
            }

            StringBuilder t = new StringBuilder();
            for (int i = 0; i < 26 && t.length() < a; i++) {
                if (used[i] == 0) {
                    t.append((char)('a' + i));
                }
            }

            // If we still need more letters (shouldn't happen with correct logic)
            while (t.length() < a) {
                t.append('a');
            }

            s.append(t.toString());
        }

        // Count distinct letters in segment [l, r] (1-indexed)
        int[] count = new int[26];
        for (int i = l - 1; i < r; i++) {
            count[s.charAt(i) - 'a'] = 1;
        }

        int distinct = 0;
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) distinct++;
        }

        out.print(distinct);
        out.close();
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void printf(String format, Object... objects) {
            writer.printf(format, objects);
        }

        public void close() {
            writer.close();
        }

        public void flush() {
            writer.flush();
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (this.numChars == -1) {
                throw new InputMismatchException();
            } else {
                if (this.curChar >= this.numChars) {
                    this.curChar = 0;

                    try {
                        this.numChars = this.stream.read(this.buf);
                    } catch (IOException var2) {
                        throw new InputMismatchException();
                    }

                    if (this.numChars <= 0) {
                        return -1;
                    }
                }

                return this.buf[this.curChar++];
            }
        }

        public int nextInt() {
            int c;
            for (c = this.read(); isSpaceChar(c); c = this.read()) {
                ;
            }

            byte sgn = 1;
            if (c == 45) {
                sgn = -1;
                c = this.read();
            }

            int res = 0;

            while (c >= 48 && c <= 57) {
                res *= 10;
                res += c - 48;
                c = this.read();
                if (isSpaceChar(c)) {
                    return res * sgn;
                }
            }

            throw new InputMismatchException();
        }

        public static boolean isSpaceChar(int c) {
            return c == 32 || c == 10 || c == 13 || c == 9 || c == -1;
        }

    }
}
